import { Injectable } from "@angular/core";
import { BaseStyle } from "primeng/base";

export const TYPOGRAPHY_THEMES = ({ dt }: any) => `
    * {
        font-family: ${dt('typography.fontFamily.base')};
        box-sizing: border-box;
    }
    
    body {
        font-size: ${dt('typography.body.m.fontSize')};
        line-height: ${dt('typography.body.m.lineHeight')};
        font-weight: ${dt('typography.fontWeight.regular')};
        color: ${dt('typography.text.primary')};
    }

    /* Headings - Mapped to Heading tokens from Design System */
    h1 {
        font-size: ${dt('typography.heading.l.fontSize')};
        font-weight: ${dt('typography.fontWeight.bold')};
        line-height: ${dt('typography.heading.l.lineHeight')};
        color: ${dt('typography.text.primary')};
    }

    h2 {
        font-size: ${dt('typography.heading.m.fontSize')};
        font-weight: ${dt('typography.fontWeight.bold')};
        line-height: ${dt('typography.heading.m.lineHeight')};
        color: ${dt('typography.text.primary')};
    }

    h3 {
        font-size: ${dt('typography.heading.s.fontSize')};
        font-weight: ${dt('typography.fontWeight.semibold')};
        line-height: ${dt('typography.heading.s.lineHeight')};
        color: ${dt('typography.text.primary')};
    }

    h4 {
        font-size: ${dt('typography.body.l.fontSize')};
        font-weight: ${dt('typography.fontWeight.semibold')};
        line-height: ${dt('typography.body.l.lineHeight')};
        color: ${dt('typography.text.primary')};
    }

    h5 {
        font-size: ${dt('typography.body.m.fontSize')};
        font-weight: ${dt('typography.fontWeight.semibold')};
        line-height: ${dt('typography.body.m.lineHeight')};
        color: ${dt('typography.text.primary')};
    }

    h6 {    
        font-size: ${dt('typography.body.s.fontSize')};
        font-weight: ${dt('typography.fontWeight.semibold')};
        line-height: ${dt('typography.body.s.lineHeight')};
        color: ${dt('typography.text.primary')};
    }

    /* Display Styles - For prominent numbers/information */
    .display-l {
        font-size: ${dt('typography.display.l.fontSize')};
        line-height: ${dt('typography.display.l.lineHeight')};
    }

    .display-m {
        font-size: ${dt('typography.display.m.fontSize')};
        line-height: ${dt('typography.display.m.lineHeight')};
    }

    .display-s {
        font-size: ${dt('typography.display.s.fontSize')};
        line-height: ${dt('typography.display.s.lineHeight')};
    }

    /* Body Text Styles */
    .body-l {
        font-size: ${dt('typography.body.l.fontSize')};
        line-height: ${dt('typography.body.l.lineHeight')};
    }

    .body-m {
        font-size: ${dt('typography.body.m.fontSize')};
        line-height: ${dt('typography.body.m.lineHeight')};
    }

    .body-s {
        font-size: ${dt('typography.body.s.fontSize')};
        line-height: ${dt('typography.body.s.lineHeight')};
    }

    /* Number Styles - Roboto Mono for technical content */
    .number-l,
    code.number-l {
        font-family: ${dt('typography.fontFamily.mono')};
        font-size: ${dt('typography.number.l.fontSize')};
        line-height: ${dt('typography.number.l.lineHeight')};
    }

    .number-m,
    code.number-m {
        font-family: ${dt('typography.fontFamily.mono')};
        font-size: ${dt('typography.number.m.fontSize')};
        line-height: ${dt('typography.number.m.lineHeight')};
    }

    .number-s,
    code.number-s {
        font-family: ${dt('typography.fontFamily.mono')};
        font-size: ${dt('typography.number.s.fontSize')};
        line-height: ${dt('typography.number.s.lineHeight')};
    }

    /* Text Color Utilities */
    .text-primary {
        color: ${dt('typography.text.primary')};
    }

    .text-subtitle {
        color: ${dt('typography.text.subtitle')};
    }

    .text-secondary {
        color: ${dt('typography.text.secondary')};
    }

    .text-tertiary {
        color: ${dt('typography.text.tertiary')};
    }

    .text-disabled {
        color: ${dt('typography.text.disabled')};
    }

    .text-white {
        color: ${dt('typography.text.white')};
    }

    .text-brand {
        color: ${dt('typography.text.brand')};
    }

    .text-focus {
        color: ${dt('typography.text.focus')};
    }

    .text-link {
        color: ${dt('typography.text.link')};
        cursor: pointer;
    }

    /* Font Weight Utilities */
    .font-regular {
        font-weight: ${dt('typography.fontWeight.regular')};
    }

    .font-medium {
        font-weight: ${dt('typography.fontWeight.medium')};
    }

    .font-semibold {
        font-weight: ${dt('typography.fontWeight.semibold')};
    }

    .font-bold {
        font-weight: ${dt('typography.fontWeight.bold')};
    }
    .text-center {
        text-align: center;
    }

    /* Code and Pre */
    code, pre {
        font-family: ${dt('typography.fontFamily.mono')};
    }

    /* PrimeNG Button Adjustments */
    p-button {
        line-height: ${dt('typography.body.m.lineHeight')};
    }

    .p-button-lg {
        line-height: ${dt('typography.body.l.lineHeight')};
    }
`

export const TYPOGRAPHY_CLASSES = {
    root: 'typography',
}

@Injectable({
    providedIn: 'root',
})

export class UBCKTypographyStyles extends BaseStyle {
    override name = 'typographyConfig';
    override classes = TYPOGRAPHY_CLASSES
    override style = TYPOGRAPHY_THEMES;

}